    23	    /**
    24	     * An incident is reimbursed damage by damage: the office settles each
    25	     * reported damage on its own and pays the sum, because the deductible is
    26	     * charged per damage event rather than once for the incident.
    27	     *
    28	     * The MHPCO keeps intermediate amounts as fractions and rounds only the
    29	     * final payout, so each damage is settled as a fraction and the sum is
    30	     * narrowed to whole G once, here. No active example yields a fractional
    31	     * payout, so that narrowing is exact today; how the office rounds one
    32	     * that is not -- in its own favour, down -- is a decision no active
    33	     * behaviour has asked for, and this is where it will be made.
    34	     */
    35	    public static int forIncident(Incident incident, Coverage coverage) {
    36	        return incident.damages().stream()
    37	                .map(damage -> forDamage(damage, coverage.damagedIn(damage)))
    38	                .reduce(BigDecimal.ZERO, BigDecimal::add)
    39	                .intValueExact();
    40	    }
    41	
    42	    /**
    43	     * One reported damage is settled in two steps the MHPCO decides
    44	     * separately: how much of the damage it reimburses at all, and then the
    45	     * deductible it charges for the damage event.
    46	     */
    47	    private static BigDecimal forDamage(Damage damage, Item damagedItem) {
    48	        return reimbursableAmount(damage, damagedItem)
    49	                .subtract(BigDecimal.valueOf(DEDUCTIBLE_PER_DAMAGE_IN_G));
    50	    }
    51	
    52	    /**
    53	     * How much of a reported damage the MHPCO reimburses, before the
    54	     * deductible: damage to a highly enchanted item is reimbursed at half,
    55	     * anything else in full.
    56	     */
    57	    private static BigDecimal reimbursableAmount(Damage damage, Item damagedItem) {
    58	        if (isHighlyEnchanted(damagedItem)) {
    59	            return Percentage.of(damage.amount(), HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT);
    60	        }
    61	        return BigDecimal.valueOf(damage.amount());
    62	    }
